/**
 *
 * InputTags allows entering multiple values as removable chips with optional autocomplete suggestions.
 *
 * [Live Demo](https://www.primevue.dev/inputtags/)
 *
 * @module inputtagsstyle
 *
 */
import type { BaseStyle, BaseStyleModule } from '@primevue/core/base/style';

export enum InputTagsClasses {
    /**
     * Class name of the root element
     */
    root = 'p-inputtags',
    /**
     * Class name of the item element
     */
    item = 'p-inputtags-item',
    /**
     * Class name of the chip icon element
     */
    chipIcon = 'p-inputtags-chip-icon',
    /**
     * Class name applied to the nested AutoComplete instance.
     */
    pcAutoComplete = 'p-inputtags-autocomplete'
}

export interface InputTagsStyle extends BaseStyle {}

declare const InputTagsStyle: BaseStyleModule;

export default InputTagsStyle;
